#include <iostream>
#include <vector>
#include <unordered_map>
#include <cmath>
#include <algorithm>

int main() {
    // Generate list of primes up to 6000
    std::vector<int> primes_list;
    for (int candidate_num = 2; candidate_num < 6000; ++candidate_num) {
        bool is_prime_flag = true;
        for (int prime_check : primes_list) {
            if (prime_check * prime_check > candidate_num) {
                break;
            }
            if (candidate_num % prime_check == 0) {
                is_prime_flag = false;
                break;
            }
        }
        if (is_prime_flag) {
            primes_list.push_back(candidate_num);
        }
    }

    // Function to get prime factors of a number
    auto get_prime_factors = [&](int number) {
        std::unordered_map<int, int> factors_dict;
        for (int prime : primes_list) {
            if (prime * prime > number) {
                break;
            }
            if (number % prime == 0) {
                int count = 0;
                while (number % prime == 0) {
                    number /= prime;
                    ++count;
                }
                factors_dict[prime] = count;
            }
        }
        if (number > 1) {
            factors_dict[number] = 1;
        }
        return factors_dict;
    };

    // Function to get all factors of a number
    auto all_factors = [&](int number) {
        auto prime_factors = get_prime_factors(number);
        std::vector<int> result_factors = {1};
        for (const auto& pf : prime_factors) {
            int prime = pf.first;
            int exp_count = pf.second;
            std::vector<int> new_factors;
            for (int val : result_factors) {
                for (int exp = 0; exp <= exp_count; ++exp) {
                    int new_val = val;
                    for (int e = 0; e < exp; ++e) {
                        new_val *= prime;
                    }
                    new_factors.push_back(new_val);
                }
            }
            result_factors = new_factors;
        }
        return result_factors;
    };

    int x, y;
    std::cin >> x >> y;

    // Main process function
    auto main_process = [&](int n, int m) {
        std::unordered_map<int, int> f_values;
        f_values[0] = 0;
        f_values[1] = 1;
        f_values[2] = 2;
        for (int i = 3; i <= n; ++i) {
            int val = 2 * f_values[i - 1];
            for (int divisor : all_factors(i)) {
                if (divisor >= 2 && divisor <= i) {
                    int quotient1 = i / divisor;
                    int quotient2 = (i - 1) / divisor;
                    val += f_values[quotient1] - f_values[quotient2];
                }
            }
            val %= m;
            f_values[i] = val;
        }
        return f_values[n];
    };

    std::cout << main_process(x, y) << std::endl;

    return 0;
}
